public class ScheduleDataProvider : IScheduleDataProvider
{
    private readonly ICalendarService _calendar;

    public async Task<IReadOnlyList<SchedulerEvent>> GetEventsAsync(
        DateTime start, DateTime end, 
        IReadOnlyList<string>? resourceIds = null,
        CancellationToken ct = default)
    {
        return await _calendar.GetEventsAsync(start, end, resourceIds, ct);
    }

    public async Task<IReadOnlyList<SchedulerResource>> GetResourcesAsync(
        CancellationToken ct = default)
    {
        return await _calendar.GetResourcesAsync(ct);
    }

    public async Task<SchedulerEvent?> CreateEventAsync(
        SchedulerEvent eventData, CancellationToken ct = default)
    {
        return await _calendar.CreateEventAsync(eventData, ct);
    }

    public async Task<bool> UpdateEventAsync(
        SchedulerEvent eventData, CancellationToken ct = default)
    {
        return await _calendar.UpdateEventAsync(eventData, ct);
    }

    public async Task<bool> DeleteEventAsync(
        string eventId, CancellationToken ct = default)
    {
        return await _calendar.DeleteEventAsync(eventId, ct);
    }
}
